/// The general data of the tree, NOT including the structure or autogenerated data
#[derive(serde::Deserialize, serde::Serialize)]
pub struct TreeData {
    pub title: String,
    pub description: Option<String>,
    pub book_name: Option<String>,
    pub book_edition: Option<String>,
    pub book_isbn: Option<String>,
    pub book_chapter: Option<String>,
    pub book_exercise: Option<String>,
    pub assignment_text: Option<String>,
    pub published: bool,
}

